import EurekaKit
import Foundation

/// Locations of pricing files (EurekaUsage never touches Bundle; the app layer passes them in)
public struct PricingPaths: Sendable {
    /// Bundled handwritten table Resources/pricing.json
    public var bundledTable: URL?
    /// Bundled price catalog snapshot Resources/pricing-catalog.json (generated by make
    /// pricing-catalog before each release)
    public var bundledSnapshot: URL?
    /// Cache of the last successfully fetched catalog (kept forever)
    public var cache: URL?
    /// User override file (top layer)
    public var override: URL?

    public init(bundledTable: URL?, bundledSnapshot: URL?, cache: URL?, override: URL?) {
        self.bundledTable = bundledTable
        self.bundledSnapshot = bundledSnapshot
        self.cache = cache
        self.override = override
    }
}

/// Where the active price catalog came from (shown in Settings)
public enum CatalogOrigin: RawRepresentable, Hashable, Sendable {
    case none
    case snapshot
    case cache
    case remote

    /// Used only for display in Settings; follows the interface language when read.
    public var rawValue: String {
        switch self {
        case .none: return L10n.text("None", zhHans: "无")
        case .snapshot: return L10n.text("Bundled snapshot", zhHans: "随包快照")
        case .cache: return L10n.text("Local cache", zhHans: "本地缓存")
        case .remote: return L10n.text("Remote", zhHans: "远程")
        }
    }

    /// Accepts the original Chinese raw values as well as the English display values.
    public init?(rawValue: String) {
        switch rawValue {
        case "None", "无": self = .none
        case "Bundled snapshot", "随包快照": self = .snapshot
        case "Local cache", "本地缓存": self = .cache
        case "Remote", "远程": self = .remote
        default: return nil
        }
    }
}

/// Process-wide price table holder: holds the current PricingTable under a lock and swaps it
/// atomically when a new catalog arrives. UsageService / SessionBrowserService / dashboards all
/// read from here, so pricing is consistent at any given moment.
public final class PricingCatalogStore: @unchecked Sendable {
    public static let shared = PricingCatalogStore()

    private let lock = NSLock()
    private var paths: PricingPaths?
    private var table = PricingTable(models: [])
    private var catalog = PriceCatalog.empty
    private var origin = CatalogOrigin.none
    private var revisionValue = 0

    public init() {}

    public var current: PricingTable {
        lock.lock()
        defer { lock.unlock() }
        return table
    }

    public var currentCatalog: PriceCatalog {
        lock.lock()
        defer { lock.unlock() }
        return catalog
    }

    public var currentOrigin: CatalogOrigin {
        lock.lock()
        defer { lock.unlock() }
        return origin
    }

    /// Incremented on every swap; callers use it to decide whether to recompute costs
    public var revision: Int {
        lock.lock()
        defer { lock.unlock() }
        return revisionValue
    }

    /// First load: takes the newer of disk cache and bundled snapshot per source (a release that
    /// updates the snapshot beats an old cache). Idempotent.
    public func loadIfNeeded(paths: PricingPaths) {
        lock.lock()
        let loaded = self.paths != nil
        lock.unlock()
        guard !loaded else { return }
        let snapshot = paths.bundledSnapshot.flatMap(Self.readCatalog) ?? .empty
        let cached = paths.cache.flatMap(Self.readCatalog) ?? .empty
        let merged = PriceCatalog.newest(cached, snapshot)
        let origin: CatalogOrigin
        if merged.isEmpty {
            origin = .none
        } else if !cached.isEmpty, merged.litellmMeta == cached.litellmMeta
            || merged.modelsDevMeta == cached.modelsDevMeta {
            origin = .cache
        } else {
            origin = .snapshot
        }
        replace(paths: paths, catalog: merged, origin: origin)
    }

    /// A newly fetched catalog: swap it in and return the new revision
    @discardableResult
    public func install(catalog: PriceCatalog, origin: CatalogOrigin = .remote) -> Int {
        lock.lock()
        let paths = self.paths
        lock.unlock()
        guard let paths else { return revision }
        return replace(paths: paths, catalog: catalog, origin: origin)
    }

    /// The user edited pricing.json: keep the catalog, rebuild the table
    @discardableResult
    public func reloadOverride() -> Int {
        lock.lock()
        let paths = self.paths
        let catalog = self.catalog
        let origin = self.origin
        lock.unlock()
        guard let paths else { return revision }
        return replace(paths: paths, catalog: catalog, origin: origin)
    }

    @discardableResult
    private func replace(paths: PricingPaths, catalog: PriceCatalog, origin: CatalogOrigin) -> Int {
        let table = PricingTable.load(
            bundledURL: paths.bundledTable, overrideURL: paths.override, catalog: catalog)
        lock.lock()
        defer { lock.unlock() }
        self.paths = paths
        self.table = table
        self.catalog = catalog
        self.origin = origin
        revisionValue += 1
        return revisionValue
    }

    // MARK: - Serialization

    public static func encode(_ catalog: PriceCatalog) throws -> Data {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .secondsSince1970
        encoder.outputFormatting = [.sortedKeys]
        return try encoder.encode(catalog)
    }

    public static func decode(_ data: Data) throws -> PriceCatalog {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .secondsSince1970
        return try decoder.decode(PriceCatalog.self, from: data)
    }

    /// Reads the cache/snapshot: missing or corrupt file → nil (falls through to the next layer, no
    /// error)
    static func readCatalog(_ url: URL) -> PriceCatalog? {
        guard let data = try? Data(contentsOf: url) else { return nil }
        return try? decode(data)
    }
}
